// es.yaml rule es.commas def esSinoNegated
export function esSinoNegated(at: SpanishAround, k: number, between: number): boolean {
  if (!(k <= 12)) return false;
  const word = at.prev(k);
  if (!(word && !ES_EXCEPTIVE.has(word))) return false;
  return ES_NEGATIONS.has(word)
    ? between >= 2
    : esSinoNegated(at, k + 1, between + (ES_CLITICS.has(word) ? 0 : 1));
}

// es.yaml rule es.commas def esCommaBeforeSino
export function esCommaBeforeSino(tokens: SpanishTokens, i: number) {
  if (!(tokens[i].lower === "sino" && !!tokens[i - 1]?.word && !tokens[i].broken)) return false;
  if (!(esAround(tokens, i).next() === "que")) return false;
  return esSinoNegated(esAround(tokens, i), 1, 0);
}

// es.yaml rule es.commas def esClauseVerb
export function esClauseVerb(word: string) {
  return (
    ES_COMMON_FINITE.has(word) ||
    (!!word &&
      esFiniteVerb(word) &&
      !esIsNoun(word) &&
      !esGenderedForm(word) &&
      !esParticiple(word))
  );
}

// es.yaml rule es.commas def esClauseVerbBefore
export function esClauseVerbBefore(at: SpanishAround, back: number, last: number): boolean {
  return back > last || !at.prev(back)
    ? false
    : esClauseVerb(at.prev(back))
      ? true
      : esClauseVerbBefore(at, back + 1, last);
}

// es.yaml rule es.commas def esPastClitics
export function esPastClitics(at: SpanishAround, k: number): number {
  return k < 5 && ES_CLITICS.has(at.next(k)) ? esPastClitics(at, k + 1) : k;
}

// es.yaml rule es.commas def esCommaBeforePero
export function esCommaBeforePero(tokens: SpanishTokens, i: number) {
  if (!(tokens[i].lower === "pero" && !!tokens[i - 1]?.word && !tokens[i].broken)) return false;
  const at = esAround(tokens, i);
  const k = at.next(1) === "ya" ? 2 : 1;
  if (!ES_NEGATIONS.has(at.next(k))) return false;
  if (!esClauseVerb(at.next(esPastClitics(at, k + 1)))) return false;
  return esClauseVerbBefore(at, 1, 10);
}

// es.yaml rule es.commas def esCommaBeforeCausal
export function esCommaBeforeCausal(tokens: SpanishTokens, i: number) {
  if (!(/^(?:ya|puesto)$/u.test(tokens[i].lower) && !tokens[i].broken)) return false;
  const at = esAround(tokens, i);
  if (!(at.next() === "que" && !!at.next(2))) return false;
  const before = at.prev();
  if (!(
    before &&
    !ES_CLITICS.has(before) &&
    !ES_NEGATIONS.has(before) &&
    !ES_CONJUNCTIONS.has(before)
  ))
    return false;
  if (
    ES_DETERMINERS.has(before) ||
    esClauseVerb(before) ||
    esParticiple(before) ||
    esIsInfinitive(before)
  )
    return false;
  if (
    tokens[i].lower === "puesto" &&
    (ES_DETERMINERS.has(at.prev(2)) || /^(?:al|del)$/u.test(at.prev(2)))
  )
    return false;
  return esClauseVerbBefore(at, 2, 10);
}

// es.yaml rule es.commas def esMarkSoon
export function esMarkSoon(tokens: SpanishTokens, k: number, end: number): boolean {
  return k < end && tokens[k] && !tokens[k].broken
    ? /^[,;:—–()]$/u.test(tokens[k].text) || esMarkSoon(tokens, k + 1, end)
    : false;
}

// es.yaml rule es.commas def esSubjectComma
export function esSubjectComma(tokens: SpanishTokens, i: number) {
  if (!(ES_SUBJECT_DETERMINERS.has(tokens[i].lower) && esAround(tokens, i).starts)) return -1;
  if (/^[¿¡]$/u.test(tokens[i - 1]?.text ?? "")) return -1;
  const nounToken = tokens[i + 1];
  const pronoun = /^(?:estos|estas|esos|esas|aquellos|aquellas)$/u.test(tokens[i].lower);
  const noun =
    pronoun && nounToken?.text === ","
      ? { plural: true }
      : nounToken?.word && !nounToken.broken
        ? esReadNoun(nounToken.lower)
        : null;
  if (!(noun && !ES_NOT_SUBJECT_NOUNS.has(nounToken.lower))) return -1;
  const after = nounToken.text === "," ? i + 1 : i + 2;
  const adjective = tokens[after];
  const comma =
    after === i + 2 && adjective?.word && !adjective.broken && !esFiniteVerb(adjective.lower)
      ? after + 1
      : after;
  if (!(tokens[comma]?.text === "," && !tokens[comma].broken)) return -1;
  const lead = /^(?:no|se)$/u.test(tokens[comma + 1]?.lower ?? "") ? 1 : 0;
  const verb = tokens[comma + 1 + lead];
  if (!(verb?.word && !verb.broken && !/^\p{Lu}/u.test(tokens[comma + 1].text))) return -1;
  const word = verb.lower;
  const plural = ES_PLURAL_COPULA.has(word)
    ? true
    : ES_SINGULAR_COPULA.has(word)
      ? false
      : !/(?:n|[aeó])$/u.test(word) ||
          !esFiniteVerb(word) ||
          esIsNoun(word) ||
          esAttributeOf(word) ||
          esSubjunctiveLike(word) ||
          ES_CLITICS.has(word)
        ? null
        : word.endsWith("n");
  if (!(plural === noun.plural)) return -1;
  if (esMarkSoon(tokens, comma + 2, comma + 7)) return -1;
  return comma;
}

// es.yaml rule es.commas def esPhraseAt
export function esPhraseAt(tokens: SpanishTokens, i: number, phrase: readonly string[]) {
  return phrase.every(
    (word, k) =>
      !!tokens[i + k]?.word && tokens[i + k].lower === word && !(k > 0 && tokens[i + k].broken),
  )
    ? i + phrase.length - 1
    : -1;
}

// es.yaml rule es.commas def esConnectorEnd
export function esConnectorEnd(tokens: SpanishTokens, i: number, phrase: readonly string[]) {
  const last = esPhraseAt(tokens, i, phrase);
  const after = tokens[last + 1];
  const next = after?.lower ?? "";
  return !after?.word || after.broken || ES_NOT_CONNECTOR_AFTER.has(next)
    ? -1
    : phrase.join(" ") === "por tanto" && esIsNoun(next)
      ? -1
      : /mente$/u.test(phrase[0]) && (esAttributeOf(next) || /^(?:tuy|suy|vuestr)/u.test(next))
        ? -1
        : last;
}

// es.yaml rule es.commas def esAddressee
export function esAddressee(tokens: SpanishTokens, at: number) {
  const mine = tokens[at]?.lower === "mi" && !tokens[at].broken ? at + 1 : at;
  const k =
    /^querid[oa]s?$/u.test(tokens[mine]?.lower ?? "") &&
    ES_ADDRESSED.has(tokens[mine + 1]?.lower ?? "")
      ? mine + 1
      : mine;
  const token = tokens[k];
  if (!(token?.word && !token.broken)) return -1;
  return ES_ADDRESSED.has(token.lower) ? k : k === at && /^\p{Lu}\p{Ll}/u.test(token.text) ? k : -1;
}

// es.yaml rule es.commas def esCommaAfter
export function esCommaAfter(ctx: DetectContext, tokens: SpanishTokens, i: number) {
  return esReplaceToken(
    ctx,
    tokens[i],
    [`${tokens[i].lower},`],
    "spanishTypography",
    "review_msg_spanish_comma",
    tokens[i + 1],
  );
}

// es.yaml rule es.quoteSpaces def esQuoteMarks
export function esQuoteMarks(text: string, k: number, end: number): number[] {
  return k >= 0 && k < end ? [k, ...esQuoteMarks(text, text.indexOf('"', k + 1), end)] : [];
}

// es.yaml rule es.quoteSpaces def esQuotePairSpaces
export function esQuotePairSpaces(ctx: DetectContext, open: number, close: number) {
  const inner = ctx.text.slice(open + 1, close);
  if (!(inner.trim() && inner.length <= 200 && !namedExampleBefore(ctx.text, open))) return [];
  const lead = /^[ \t ]+(?=[\p{L}\p{N}¿¡])/u.exec(inner)?.[0].length ?? 0;
  const trail = /(?<=[\p{L}\p{N}.!?…])[ \t ]+$/u.exec(inner)?.[0].length ?? 0;
  return [
    lead && open >= ctx.from && open < ctx.to
      ? {
          ruleId: "commaPeriodSpacing" as const,
          messageKey: "review_msg_space_after_opening_mark" as const,
          range: { start: open, end: open + 1 + lead },
          alternatives: ['"'],
          context: { start: open, end: close + 1 },
          bulkBlock: "context-dependent" as const,
        }
      : null,
    trail && close >= ctx.from && close < ctx.to
      ? {
          ruleId: "commaPeriodSpacing" as const,
          messageKey: "review_msg_space_before_mark" as const,
          range: { start: close - trail, end: close + 1 },
          alternatives: ['"'],
          context: { start: open, end: close + 1 },
          bulkBlock: "context-dependent" as const,
        }
      : null,
  ].filter((finding) => finding !== null);
}

// es.yaml rule es.dashes def esLongDash
export function esLongDash(ctx: DetectContext, start: number, end: number) {
  return start < ctx.from || start >= ctx.to
    ? null
    : esFinding("emdashShortcut", "review_msg_spanish_dialogue_dash", start, end, ["—"]);
}

// es.yaml rule es.rangeDash def ES_RANGE_CODE_BEFORE
export const ES_RANGE_CODE_BEFORE =
  /(?:^|[\s(])(?:tel|teléf|tfno|tlf|teléfono|móvil|fax|whatsapp|c\.?p|código|cód|n\.?º|núm|número|ref|referencia|expediente|exp|lote|pedido|factura|matrícula|dni|nie|nif|cif|cuenta|iban|tarjeta|art|artículo|ley|decreto|modelo|versión|vuelo|línea|ruta)\.?:?(?:[ \t]{1,8}(?:es|era|será))?[ \t]{0,8}$/iu;

// es.yaml rule es.rangeDash def ES_RANGE_SCORE_BEFORE
export const ES_RANGE_SCORE_BEFORE =
  /(?:^|\s)(?:gan\p{L}*|perd\p{L}*|venc\p{L}*|empat\p{L}*|derrot\p{L}*|golea\p{L}*|marcador|resultado|partido|set|sets|tanteo)[ \t]{1,8}(?:\p{L}+[ \t]{1,8}){0,2}$/iu;

// es.yaml rule es.quotes def esQuoteMark
export function esQuoteMark(start: number, replacement: string, pairEnd: number) {
  return {
    ruleId: "spanishQuotes" as const,
    messageKey: "review_msg_spanish_quotes" as const,
    range: { start, end: start + 1 },
    alternatives: [replacement],
    context: { start: Math.max(0, start - 1), end: pairEnd },
  };
}

// es.yaml rule es.quotes def esQuotePair
export function esQuotePair(m: RegExpExecArray, ctx: DetectContext, open: string, close: string) {
  if (!(m.index >= ctx.from)) return null;
  const end = m.index + m[0].length;
  if (ctx.text.slice(m.index, end).includes("￼") || namedExampleBefore(ctx.text, m.index))
    return null;
  return [esQuoteMark(m.index, open, end), esQuoteMark(end - 1, close, end)];
}

/** The frame fixes, by the name their frames give ("@<rule id>/<frame>"). */
export const FIXERS: Readonly<Record<string, AnyFixer>> = {
  // es.yaml rule es.estarAccents frame 1
  "@es.estarAccents/1": (m: RegExpExecArray, ctx: DetectContext): MatchResult => {
    const tokens = esTokens(ctx);
    const i = esTokenAt(tokens, m.index);
    if (!(i >= 0)) return null;
    const token = tokens[i];
    if (!(token.word && token.start >= ctx.from && token.start < ctx.to)) return null;
    const at = esAround(tokens, i);
    const lower = token.lower;
    const verb =
      lower === "esta"
        ? esEstarReading(at, false) && "está"
        : lower === "estas"
          ? esEstarReading(at, true) && "estás"
          : lower === "este"
            ? esSubjunctiveReading(at) && "esté"
            : false;
    const demonstrative =
      lower === "está"
        ? "esta"
        : lower === "estás"
          ? "estas"
          : lower === "esté"
            ? "este"
            : undefined;
    return [
      verb
        ? esReplaceToken(
            ctx,
            token,
            [verb],
            "spanishAccents",
            "review_msg_spanish_accent",
            tokens[i + 1],
          )
        : null,
      demonstrative && esDemonstrativeReading(at)
        ? esReplaceToken(
            ctx,
            token,
            [demonstrative],
            "spanishAccents",
            "review_msg_spanish_accent_extra",
            tokens[i + 1],
          )
        : null,
    ].filter((finding) => finding !== null);
  },
  // es.yaml rule es.diacritics frame 1
  "@es.diacritics/1": (m: RegExpExecArray, ctx: DetectContext): MatchResult => {
    const tokens = esTokens(ctx);
    const i = esTokenAt(tokens, m.index);
    if (!(i >= 0)) return null;
    const token = tokens[i];
    if (!(token.word && token.start >= ctx.from && token.start < ctx.to)) return null;
    const at = esAround(tokens, i);
    const question = esInterrogative(at);
    const fix = question ?? esRelative(at) ?? esMonosyllable(at);
    if (!fix) return null;
    return esReplaceToken(
      ctx,
      token,
      [fix],
      "spanishAccents",
      question
        ? "review_msg_spanish_interrogative"
        : /[áéíóú]/u.test(fix)
          ? "review_msg_spanish_accent"
          : "review_msg_spanish_accent_extra",
      tokens[i + 1],
    );
  },
  // es.yaml rule es.prefixes frame 1
  "@es.prefixes/1": (m: RegExpExecArray, ctx: DetectContext): MatchResult => {
    if (!(m.index >= ctx.from)) return null;
    const prefix = m[1].toLowerCase();
    const hyphen = m[2];
    if (!hyphen && prefix === "ex") return null;
    const word = m[3];
    const lower = word.toLowerCase();
    if (hyphen && ES_RELATIONAL_PREFIXES.has(prefix) && !esIsNoun(lower)) return null;
    if (
      hyphen &&
      ES_RELATIONAL_PREFIXES.has(prefix) &&
      /(?:ense|és|ano|ana|ino|ina)s?$|eses$/u.test(lower)
    )
      return null;
    const before =
      /(\p{L}+)[ \t]+$/u
        .exec(ctx.text.slice(Math.max(0, m.index - 24), m.index))?.[1]
        .toLowerCase() ?? "";
    const graded =
      ES_GRADING_PREFIXES.has(prefix) &&
      !!esGenderedForm(lower) &&
      !esIsNoun(lower) &&
      !ES_DETERMINER.has(before);
    const det = ES_DETERMINER.get(before);
    const noun = esReadNoun(lower);
    const sized =
      ES_SIZE_PREFIXES.has(prefix) &&
      !!det &&
      !!noun &&
      !noun.paired &&
      !esAttributeOf(lower) &&
      !ES_PRENOMINAL.has(lower) &&
      (noun.invariant || noun.plural === det.slot >= 2);
    if (
      !hyphen &&
      ES_FREE_PREFIXES.has(prefix) &&
      !graded &&
      !sized &&
      !esKnownWord(esJoinPrefix(prefix, word))
    )
      return null;
    if (/^\p{Lu}/u.test(word)) return null;
    const after = /^[ \t]{1,8}(\p{L}+)/u.exec(ctx.text.slice(m.index + m[0].length))?.[1] ?? "";
    const apocope = /^(?:primer|tercer|gran|buen|mal|algún|ningún|alto|alta)$/u.test(word);
    if (
      !hyphen &&
      (apocope || esAttribute(word)) &&
      (esIsNoun(after.toLowerCase()) || esIsGenderedEntry(after.toLowerCase()))
    )
      return null;
    if (prefix === "re" && /^(?:mayor|menor|bemol|sostenido)$/u.test(word)) return null;
    if (
      esKeepsTyped(ctx, m[1]) ||
      ctx.dictionary.has(word) ||
      namedExampleBefore(ctx.text, m.index)
    )
      return null;
    return esFinding(
      "spanishConfusions",
      "review_msg_closed_compound",
      m.index,
      m.index + m[0].length,
      [esCarryCase(m[1], esJoinPrefix(prefix, word))],
      { bulkBlock: "context-dependent" },
    );
  },
  // es.yaml rule es.splitCompounds frame 1
  "@es.splitCompounds/1": (
    m: RegExpExecArray,
    ctx: DetectContext,
    frame: FrameRef,
  ): MatchResult => {
    const tokens = esTokens(ctx);
    const i = esTokenAt(tokens, m.index);
    if (!(i >= 1 && i + 1 < tokens.length)) return null;
    const first = tokens[i];
    const hyphen =
      tokens[i + 1].text === "-" && first.end === tokens[i + 1].start && !!tokens[i + 2];
    const second = hyphen ? tokens[i + 2] : tokens[i + 1];
    if (!(first.word && (second.word || hyphen) && !second.broken && first.start >= ctx.from))
      return null;
    if (!(first.start < ctx.to)) return null;
    if (hyphen && (ctx.text[second.end] === "-" || ctx.text[first.start - 1] === "-")) return null;
    const gap = ctx.text.slice(first.end, second.start);
    if (!(gap === " " || (hyphen && gap === "-"))) return null;
    if (!(/^\p{Ll}+$/u.test(second.text) && /^\p{Ll}+$/u.test(first.text))) return null;
    const at = esAround(tokens, i);
    const quoted = /^[«“"]$/u.test(tokens[i - 1].text) && !tokens[i].broken;
    const det = quoted ? esAround(tokens, i - 1).prev() : at.prev();
    const joined = esSplitCompound(at, det, first.lower, second.lower, hyphen);
    if (!(joined && !esKeepsTyped(ctx, first.lower) && !ctx.dictionary.has(second.lower)))
      return null;
    if (namedExampleBefore(ctx.text, first.start)) return null;
    if (!esResume(frame, second.end)) return null;
    return esFinding(
      "spanishConfusions",
      "review_msg_closed_compound",
      first.start,
      second.end,
      [joined],
      { bulkBlock: "context-dependent" },
    );
  },
  // es.yaml rule es.doubledCompounds frame 1
  "@es.doubledCompounds/1": (m: RegExpExecArray, ctx: DetectContext): MatchResult => {
    if (!(m.index >= ctx.from && m[1] === m[2] && !ctx.dictionary.has(m[0].toLowerCase())))
      return null;
    if (namedExampleBefore(ctx.text, m.index)) return null;
    return {
      ruleId: "spanishConfusions",
      messageKey: "review_msg_closed_compound",
      range: { start: m.index, end: m.index + m[0].length },
      alternatives: [`${m[1]}${m[2]}`],
      bulkBlock: "context-dependent",
    };
  },
  // es.yaml rule es.porque frame 1
  "@es.porque/1": (m: RegExpExecArray, ctx: DetectContext, frame: FrameRef): MatchResult => {
    const tokens = esTokens(ctx);
    const i = esTokenAt(tokens, m.index);
    if (!(i >= 0)) return null;
    if (!(tokens[i].word && tokens[i].start >= ctx.from && tokens[i].start < ctx.to)) return null;
    const phrase = esSino(tokens, i) ?? esPorquePhrase(tokens, i);
    if (!phrase) return null;
    if (!esResume(frame, tokens[phrase.end].end)) return null;
    return esReplaceToken(
      ctx,
      esSpan(ctx, tokens[i], tokens[phrase.end]),
      phrase.fix,
      "spanishConfusions",
      "review_msg_spanish_confusion",
    );
  },
  // es.yaml rule es.typography frame 1
  "@es.typography/1": (m: RegExpExecArray, ctx: DetectContext): MatchResult => {
    const tokens = esTokens(ctx);
    const i = esTokenAt(tokens, m.index);
    if (!(i >= 0)) return null;
    const token = tokens[i];
    if (!(token.start >= ctx.from && token.start < ctx.to)) return null;
    const at = esAround(tokens, i);
    const pick =
      token.word && /^[yeou]$/iu.test(token.text)
        ? ([esConjunction(at, token), "review_msg_spanish_conjunction"] as const)
        : /^\p{N}/u.test(token.text)
          ? ([esYearDot(at, token), "review_msg_spanish_year"] as const)
          : /^tics$/iu.test(token.text) && /^(?:las|estas|sus|nuevas)$/u.test(at.prev())
            ? (["TIC", "review_msg_spanish_acronym"] as const)
            : token.lower === "asín" && (token.text === "asín" || at.starts)
              ? (["así", "review_msg_typo"] as const)
              : token.word
                ? ([esCapitalName(at, token), "review_msg_spanish_lowercase_name"] as const)
                : ([null, "review_msg_spanish_conjunction"] as const);
    const fix = pick[0];
    const key = pick[1];
    const raw =
      !fix && /^\p{Lu}{2,}(?:s|S)?$/u.test(token.text)
        ? /^\p{Lu}{2,}(?:['’]s|s|S)(?!\p{L})/u.exec(ctx.text.slice(token.start))
        : null;
    const acronym = raw ? esAcronymPlural(raw[0]) : null;
    if (!(fix || acronym)) return null;
    return fix
      ? esReplaceToken(
          ctx,
          token,
          [fix],
          "spanishTypography",
          key,
          tokens[i + 1] ?? token,
          key === "review_msg_spanish_lowercase_name" || key === "review_msg_spanish_acronym",
        )
      : esReplaceToken(
          ctx,
          { ...token, end: token.start + raw![0].length, text: raw![0] },
          [acronym!],
          "spanishTypography",
          "review_msg_spanish_acronym",
          { ...token, end: token.start + raw![0].length, text: raw![0] },
          true,
        );
  },
  // es.yaml rule es.impossibleDates frame 1
  "@es.impossibleDates/1": (m: RegExpExecArray, ctx: DetectContext): MatchResult => {
    const weekday = m[1];
    const day = m[3];
    const year = m[5];
    const dayStart = m.index + (weekday ? weekday.length + m[2].length : 0);
    if (!(dayStart >= ctx.from)) return null;
    const monthIndex = esMonthNumber(m[4]);
    const yearNumber = year ? Number(year) : undefined;
    const dayNumber = Number(day);
    const fullDate =
      yearNumber !== undefined &&
      (dayNumber === 0 || dayNumber > 31) &&
      !/(?:^|[\s(])(?:el|del|al|El|Del|Al)[ \t]{1,8}$/u.test(
        ctx.text.slice(Math.max(0, dayStart - 12), dayStart),
      );
    return [
      esDayFinding(ctx, dayStart, day, monthIndex, yearNumber),
      (fullDate || (weekday && dayNumber === 0)) && !namedExampleBefore(ctx.text, m.index)
        ? esFinding(
            "spanishTypography",
            "review_msg_spanish_date",
            dayStart,
            m.index + m[0].length,
            [],
            { warningOnly: true },
          )
        : null,
      weekday &&
      yearNumber &&
      dayNumber >= 1 &&
      dayNumber <= esDaysInMonth(monthIndex, yearNumber) &&
      ES_WEEKDAY_LIST[esWeekdayOf(yearNumber, monthIndex, Number(day))] !== weekday.toLowerCase() &&
      !namedExampleBefore(ctx.text, m.index)
        ? {
            ruleId: "spanishTypography" as const,
            messageKey: "review_msg_spanish_date" as const,
            range: { start: m.index, end: m.index + weekday.length },
            alternatives: [
              esCarryCase(
                weekday,
                ES_WEEKDAY_LIST[esWeekdayOf(yearNumber, monthIndex, Number(day))],
              ),
            ],
            context: { start: m.index, end: m.index + m[0].length },
            bulkBlock: "ambiguous" as const,
          }
        : null,
      weekday &&
      !year &&
      dayNumber >= 1 &&
      dayNumber <= esDaysInMonth(monthIndex) &&
      !namedExampleBefore(ctx.text, m.index)
        ? esWeekdayNoYear(ctx, m, dayStart, monthIndex)
        : null,
    ].filter((finding) => finding !== null);
  },
  // es.yaml rule es.impossibleDates frame 2
  "@es.impossibleDates/2": (m: RegExpExecArray, ctx: DetectContext): MatchResult => {
    if (!(m.index >= ctx.from && !namedExampleBefore(ctx.text, m.index))) return null;
    return esFinding(
      "spanishTypography",
      "review_msg_spanish_date",
      m.index,
      m.index + m[0].length,
      [],
      { warningOnly: true },
    );
  },
  // es.yaml rule es.impossibleDates frame 3
  "@es.impossibleDates/3": (m: RegExpExecArray, ctx: DetectContext): MatchResult => {
    if (!(m.index >= ctx.from)) return null;
    const separator = m[2];
    const monthText = m[3];
    const yearText = m[4] ?? "";
    const month = /^\d/u.test(monthText)
      ? Number(monthText)
      : ES_MONTHS.has(monthText.toLowerCase())
        ? esMonthNumber(monthText)
        : esShortMonth(monthText);
    const day = Number(m[1]);
    const dated = ES_DATED.test(ctx.text.slice(Math.max(0, m.index - 15), m.index));
    if (!(
      yearText.length === 4 ||
      (dated &&
        !(
          !yearText &&
          (separator === "-" ||
            !/^(?:[.;:!?)]|\s{0,8}$)/u.test(ctx.text.slice(m.index + m[0].length)))
        ))
    ))
      return null;
    const impossible =
      ((month > 12 || day > 31) && (day > 12 || month > 31)) ||
      (yearText.length === 4 && (day === 0 || month === 0));
    const fullDate =
      separator === "/" &&
      yearText.length === 4 &&
      day <= 39 &&
      month <= 39 &&
      !ES_CODE_LABEL.test(ctx.text.slice(Math.max(0, m.index - 16), m.index));
    if (!(!impossible || ((dated || fullDate) && !namedExampleBefore(ctx.text, m.index))))
      return null;
    if (!(impossible || (month >= 1 && month <= 12))) return null;
    return impossible
      ? esFinding(
          "spanishTypography",
          "review_msg_spanish_date",
          m.index,
          m.index + m[0].length,
          [],
          { warningOnly: true },
        )
      : esDayFinding(
          ctx,
          m.index,
          m[1],
          month,
          yearText.length === 4
            ? Number(yearText)
            : yearText && yearText !== "00"
              ? 2000 + Number(yearText)
              : undefined,
        );
  },
  // es.yaml rule es.isoDates frame 1
  "@es.isoDates/1": (m: RegExpExecArray, ctx: DetectContext, frame: FrameRef): MatchResult => {
    const range = esInvalidIsoDate(m, ctx);
    if (!range) return null;
    return {
      ruleId: frame.ruleId,
      messageKey: frame.messageKey,
      range,
      alternatives: [],
      warningOnly: true,
    };
  },
  // es.yaml rule es.typographyMarks frame 1
  "@es.typographyMarks/1": (
    m: RegExpExecArray,
    ctx: DetectContext,
    frame: FrameRef,
  ): MatchResult => {
    return esFinding("spanishTypography", frame.messageKey, m.index, m.index + m[0].length, [
      `${m[0].slice(0, 3)}.`,
    ]);
  },
  // es.yaml rule es.typographyMarks frame 2
  "@es.typographyMarks/2": (
    m: RegExpExecArray,
    ctx: DetectContext,
    frame: FrameRef,
  ): MatchResult => {
    return esFinding("spanishTypography", frame.messageKey, m.index, m.index + m[0].length, [
      ", etc.",
      "…",
    ]);
  },
  // es.yaml rule es.typographyMarks frame 3
  "@es.typographyMarks/3": (
    m: RegExpExecArray,
    ctx: DetectContext,
    frame: FrameRef,
  ): MatchResult => {
    if (!esMarkOpen(m, ctx)) return null;
    return esMarkFix(
      m,
      frame,
      /^e?r$/u.test(m[2]) ? `${m[1]}.er` : `${m[1]}.${m[2].endsWith("a") ? "ª" : "º"}`,
    );
  },
  // es.yaml rule es.typographyMarks frame 4
  "@es.typographyMarks/4": (
    m: RegExpExecArray,
    ctx: DetectContext,
    frame: FrameRef,
  ): MatchResult => {
    if (!esMarkOpen(m, ctx)) return null;
    return esMarkFix(
      m,
      frame,
      /^g/iu.test(m[3])
        ? `${m[1]} g`
        : !/(?:^|\s)(?:las|la|sobre|hacia|desde|hasta|durante|en)\s{1,8}$/iu.test(
              ctx.text.slice(Math.max(0, m.index - 12), m.index),
            )
          ? null
          : m[3] === "h" && !m[4] && m[2]
            ? null
            : `${m[1]} h`,
    );
  },
  // es.yaml rule es.typographyMarks frame 5
  "@es.typographyMarks/5": (
    m: RegExpExecArray,
    ctx: DetectContext,
    frame: FrameRef,
  ): MatchResult => {
    if (!esMarkOpen(m, ctx)) return null;
    const noun = esReadNoun(m[4].toLowerCase());
    const fixed = noun?.gender === "f" ? "ª" : "º";
    return esMarkFix(
      m,
      frame,
      !noun?.gender ||
        noun.paired ||
        noun.plural ||
        !/^\p{Lu}?\p{Ll}+$/u.test(m[4]) ||
        fixed === m[3]
        ? null
        : `${m[1]}${m[2]}${fixed}`,
    );
  },
  // es.yaml rule es.typographyMarks frame 6
  "@es.typographyMarks/6": (
    m: RegExpExecArray,
    ctx: DetectContext,
    frame: FrameRef,
  ): MatchResult => {
    if (!esMarkOpen(m, ctx)) return null;
    return esMarkFix(m, frame, `${m[1]} °${m[2]}`);
  },
  // es.yaml rule es.typographyMarks frame 7
  "@es.typographyMarks/7": (
    m: RegExpExecArray,
    ctx: DetectContext,
    frame: FrameRef,
  ): MatchResult => {
    if (!esMarkOpen(m, ctx)) return null;
    return esMarkFix(m, frame, `${m[1]}.º `);
  },
  // es.yaml rule es.typographyMarks frame 8
  "@es.typographyMarks/8": (
    m: RegExpExecArray,
    ctx: DetectContext,
    frame: FrameRef,
  ): MatchResult => {
    if (!esMarkOpen(m, ctx)) return null;
    return esMarkFix(m, frame, `${m[0]}.`);
  },
  // es.yaml rule es.typographyMarks frame 9
  "@es.typographyMarks/9": (
    m: RegExpExecArray,
    ctx: DetectContext,
    frame: FrameRef,
  ): MatchResult => {
    if (!esMarkOpen(m, ctx)) return null;
    return esMarkFix(m, frame, esIsNoun(m[2]) && m[2].endsWith("s") ? `${m[1]} ${m[2]}` : null);
  },
  // es.yaml rule es.typographyMarks frame 10
  "@es.typographyMarks/10": (
    m: RegExpExecArray,
    ctx: DetectContext,
    frame: FrameRef,
  ): MatchResult => {
    if (!esMarkOpen(m, ctx)) return null;
    return esMarkFix(m, frame, `${m[0][0]}${m[0].slice(1).toLowerCase()}`);
  },
  // es.yaml rule es.typographyMarks frame 11
  "@es.typographyMarks/11": (
    m: RegExpExecArray,
    ctx: DetectContext,
    frame: FrameRef,
  ): MatchResult => {
    if (!esMarkOpen(m, ctx)) return null;
    return esMarkFix(m, frame, `${m[0]}.`);
  },
  // es.yaml rule es.typographyMarks frame 12
  "@es.typographyMarks/12": (
    m: RegExpExecArray,
    ctx: DetectContext,
    frame: FrameRef,
  ): MatchResult => {
    if (!esMarkOpen(m, ctx)) return null;
    return esMarkFix(
      m,
      frame,
      /(?:^|[.!?][ \t]{1,8})$/u.test(ctx.text.slice(Math.max(0, m.index - 9), m.index))
        ? `${m[0]}.`
        : "s.",
    );
  },
  // es.yaml rule es.typographyMarks frame 13
  "@es.typographyMarks/13": (
    m: RegExpExecArray,
    ctx: DetectContext,
    frame: FrameRef,
  ): MatchResult => {
    if (!esMarkOpen(m, ctx)) return null;
    return esMarkFix(m, frame, `${m[0]}.`);
  },
  // es.yaml rule es.typographyMarks frame 14
  "@es.typographyMarks/14": (
    m: RegExpExecArray,
    ctx: DetectContext,
    frame: FrameRef,
  ): MatchResult => {
    if (!esMarkOpen(m, ctx)) return null;
    return esMarkFix(m, frame, `${m[1]}. ej.`);
  },
  // es.yaml rule es.typographyMarks frame 15
  "@es.typographyMarks/15": (
    m: RegExpExecArray,
    ctx: DetectContext,
    frame: FrameRef,
  ): MatchResult => {
    if (!esMarkOpen(m, ctx)) return null;
    const fix = `${ES_ABBREVIATION_FORMS[m[1].toLowerCase()]}${m[0].includes(":") ? ":" : ""} `;
    return esMarkFix(m, frame, /^\p{Lu}/u.test(m[1]) ? fix[0].toUpperCase() + fix.slice(1) : fix);
  },
  // es.yaml rule es.typographyMarks frame 16
  "@es.typographyMarks/16": (
    m: RegExpExecArray,
    ctx: DetectContext,
    frame: FrameRef,
  ): MatchResult => {
    if (!esMarkOpen(m, ctx)) return null;
    return esMarkFix(
      m,
      frame,
      ES_PREPOSITIONS.has(m[3]) || ES_NOT_ORDINAL_AFTER.test(m[3])
        ? null
        : `${m[2]}.${/^la$/iu.test(m[1]) ? "ª" : "º"}`,
    );
  },
  // es.yaml rule es.typographyMarks frame 17
  "@es.typographyMarks/17": (
    m: RegExpExecArray,
    ctx: DetectContext,
    frame: FrameRef,
  ): MatchResult => {
    if (!esMarkOpen(m, ctx)) return null;
    return esMarkFix(m, frame, m[1]);
  },
  // es.yaml rule es.typographyMarks frame 18
  "@es.typographyMarks/18": (
    m: RegExpExecArray,
    ctx: DetectContext,
    frame: FrameRef,
  ): MatchResult => {
    if (!esMarkOpen(m, ctx)) return null;
    return esMarkFix(m, frame, m[0][0].toUpperCase() + m[0].slice(1));
  },
  // es.yaml rule es.typographyMarks frame 19
  "@es.typographyMarks/19": (
    m: RegExpExecArray,
    ctx: DetectContext,
    frame: FrameRef,
  ): MatchResult => {
    if (!esMarkOpen(m, ctx)) return null;
    return esMarkFix(m, frame, `${m[1] ?? m[3]}, ${m[2] ?? m[4]}`);
  },
  // es.yaml rule es.typographyMarks frame 20
  "@es.typographyMarks/20": (
    m: RegExpExecArray,
    ctx: DetectContext,
    frame: FrameRef,
  ): MatchResult => {
    if (!esMarkOpen(m, ctx)) return null;
    return esMarkFix(m, frame, "—");
  },
  // es.yaml rule es.typographyMarks frame 21
  "@es.typographyMarks/21": (
    m: RegExpExecArray,
    ctx: DetectContext,
    frame: FrameRef,
  ): MatchResult => {
    if (namedExampleBefore(ctx.text, m.index)) return null;
    return esFinding("spanishTypography", frame.messageKey, m.index, m.index + 2, [",", "."], {
      requiresChoice: true,
    });
  },
  // es.yaml rule es.typographyMarks frame 22
  "@es.typographyMarks/22": (m: RegExpExecArray, ctx: DetectContext): MatchResult => {
    const text = ctx.text;
    const close = m[0] === "¿" ? "?" : "!";
    const end = esClosingEnd(text, m.index + 1, Math.min(text.length, m.index + 400));
    if (!(end >= 0 && !namedExampleBefore(text, m.index))) return null;
    const last = esLastNonSpace(text, end - 1, m.index);
    return end === text.length || text[end] === "\n"
      ? /[\p{L}\p{N}]/u.test(text[last] ?? "")
        ? esFinding("spanishTypography", "review_msg_spanish_closing_mark", last, last + 1, [
            `${text[last]}${close}`,
          ])
        : null
      : text[end] === "."
        ? esFinding("spanishTypography", "review_msg_spanish_closing_mark", end, end + 1, [close])
        : null;
  },
  // es.yaml rule es.typographyMarks frame 23
  "@es.typographyMarks/23": (m: RegExpExecArray, ctx: DetectContext): MatchResult => {
    if (!(m.index >= ctx.from && !namedExampleBefore(ctx.text, m.index))) return null;
    const second = m[2] ? m.index + m[0].lastIndexOf(m[2]) : -1;
    const first = /^\d+['’]?s/u.exec(m[0])![0];
    return [
      esFinding("spanishTypography", "review_msg_spanish_decade", m.index, m.index + first.length, [
        m[1],
      ]),
      ...(m[2]
        ? [
            esFinding(
              "spanishTypography",
              "review_msg_spanish_decade",
              second,
              second + m[0].slice(second - m.index).length,
              [m[2]],
            ),
          ]
        : []),
    ];
  },
  // es.yaml rule es.commas frame 1
  "@es.commas/1": (m: RegExpExecArray, ctx: DetectContext, frame: FrameRef): MatchResult => {
    const tokens = esTokens(ctx);
    const i = esTokenAt(tokens, m.index);
    if (!(i >= 0)) return null;
    if (!tokens[i].word) return null;
    const before =
      esCommaBeforeSino(tokens, i) || esCommaBeforePero(tokens, i) || esCommaBeforeCausal(tokens, i)
        ? esCommaAfter(ctx, tokens, i - 1)
        : null;
    const comma = esSubjectComma(tokens, i);
    const subject =
      comma >= 0
        ? esReplaceToken(
            ctx,
            tokens[comma],
            [""],
            "spanishTypography",
            "review_msg_spanish_comma",
            tokens[comma + 1],
            true,
          )
        : null;
    const starts = esAround(tokens, i).starts;
    const connector = starts
      ? ES_CONNECTORS.find((phrase) => esPhraseAt(tokens, i, phrase) >= 0)
      : undefined;
    const connectorEnd = connector ? esConnectorEnd(tokens, i, connector) : -1;
    const greeting =
      connectorEnd < 0
        ? ES_GREETINGS.find((phrase) => esPhraseAt(tokens, i, phrase) >= 0)
        : undefined;
    const greetingEnd = greeting ? esPhraseAt(tokens, i, greeting) : -1;
    const greeted = greetingEnd >= 0 ? esAddressee(tokens, greetingEnd + 1) : -1;
    const greets =
      greetingEnd >= 0 &&
      greeted >= 0 &&
      (starts ||
        (ES_CLOSING_GREETINGS.has(tokens[greetingEnd].lower) &&
          esAround(tokens, greeted).endsAfter()));
    const last = connectorEnd >= 0 ? connectorEnd : greets ? greetingEnd : -1;
    const addressed = connectorEnd < 0 && greets ? greeted : -1;
    if (!(last < 0 || esResume(frame, tokens[Math.max(last, addressed)].end))) return null;
    const next = tokens[addressed + 1];
    return [
      before,
      subject,
      ...(last < 0
        ? []
        : [
            esCommaAfter(ctx, tokens, last),
            addressed >= 0 && next?.word && !next.broken && ES_CLAUSE_OPENERS.has(next.lower)
              ? esCommaAfter(ctx, tokens, addressed)
              : null,
          ]),
    ].filter((finding) => finding !== null);
  },
  // es.yaml rule es.missingSpace frame 1
  "@es.missingSpace/1": (m: RegExpExecArray, ctx: DetectContext): MatchResult => {
    if (/\.\p{L}{1,3}$/u.test(ctx.text.slice(Math.max(0, m.index - 4), m.index))) return null;
    if (namedExampleBefore(ctx.text, m.index)) return null;
    return {
      ruleId: "commaPeriodSpacing",
      messageKey: "review_msg_space_after_mark",
      range: { start: m.index, end: m.index + m[0].length },
      alternatives: [`${m[0].trim()} `],
      context: { start: Math.max(0, m.index - 16), end: Math.min(ctx.text.length, m.index + 16) },
      bulkBlock: "context-dependent",
    };
  },
  // es.yaml rule es.missingSpace frame 2
  "@es.missingSpace/2": (m: RegExpExecArray, ctx: DetectContext): MatchResult => {
    const word = /\S*$/u.exec(ctx.text.slice(Math.max(0, m.index - 32), m.index))![0];
    if (namedExampleBefore(ctx.text, m.index) || /[&#=/]/u.test(word)) return null;
    return {
      ruleId: "commaPeriodSpacing",
      messageKey: m[0].startsWith(";")
        ? "review_msg_space_after_mark"
        : "review_msg_space_before_mark",
      range: { start: m.index, end: m.index + m[0].length },
      alternatives: [m[0].startsWith(";") ? "; " : m[0].trim()],
      context: { start: Math.max(0, m.index - 16), end: Math.min(ctx.text.length, m.index + 16) },
      bulkBlock: "context-dependent",
    };
  },
  // es.yaml rule es.quoteSpaces frame 1
  "@es.quoteSpaces/1": (m: RegExpExecArray, ctx: DetectContext): MatchResult => {
    const text = ctx.text;
    const lineStart = text.lastIndexOf("\n", m.index - 1) + 1;
    const lineEnd = m.index + m[0].length - (m[0].endsWith("\n") ? 1 : 0);
    const marks = esQuoteMarks(text, text.indexOf('"', lineStart), lineEnd);
    const usable =
      marks.length >= 2 &&
      marks.length % 2 === 0 &&
      !marks.some((k) => /\d/.test(text[k - 1] ?? ""));
    return usable
      ? marks.flatMap((open, p) => (p % 2 ? [] : esQuotePairSpaces(ctx, open, marks[p + 1])))
      : [];
  },
  // es.yaml rule es.dashes frame 1
  "@es.dashes/1": (m: RegExpExecArray, ctx: DetectContext): MatchResult => {
    if (namedExampleBefore(ctx.text, m.index)) return null;
    return esLongDash(ctx, m.index, m.index + m[0].length);
  },
  // es.yaml rule es.dashes frame 2
  "@es.dashes/2": (m: RegExpExecArray, ctx: DetectContext): MatchResult => {
    if (namedExampleBefore(ctx.text, m.index)) return null;
    const close = m.index + m[0].length - 1;
    return [esLongDash(ctx, m.index, m.index + 1), esLongDash(ctx, close, close + 1)].filter(
      (dash) => dash !== null,
    );
  },
  // es.yaml rule es.rangeDash frame 1
  "@es.rangeDash/1": (m: RegExpExecArray, ctx: DetectContext): MatchResult => {
    if (!(m.index >= ctx.from && !namedExampleBefore(ctx.text, m.index))) return null;
    const a = m[1];
    const b = m[3];
    if (a[0] === "0" || b[0] === "0" || (a.length === 3 && b.length === 4)) return null;
    const last = a.length === 4 && b.length === 2 ? Number(a.slice(0, 2) + b) : Number(b);
    if (!(last > Number(a))) return null;
    const before = ctx.text.slice(Math.max(0, m.index - 48), m.index);
    if (ES_RANGE_CODE_BEFORE.test(before) || ES_RANGE_SCORE_BEFORE.test(before)) return null;
    return esFinding(
      "emdashShortcut",
      "review_msg_range_dash",
      m.index + a.length,
      m.index + a.length + m[2].length,
      ["–"],
      {
        context: { start: m.index, end: m.index + m[0].length },
      },
    );
  },
  // es.yaml rule es.decimalComma frame 1
  "@es.decimalComma/1": (m: RegExpExecArray, ctx: DetectContext): MatchResult => {
    if (!(m.index >= ctx.from && !namedExampleBefore(ctx.text, m.index))) return null;
    return {
      ruleId: "spanishTypographyStyle",
      messageKey: "review_msg_spanish_decimal",
      range: { start: m.index, end: m.index + m[0].length },
      alternatives: [m[0].replace(/[.,]/gu, (c) => (c === "." ? "," : "."))],
    };
  },
  // es.yaml rule es.decimalComma frame 2
  "@es.decimalComma/2": (m: RegExpExecArray, ctx: DetectContext): MatchResult => {
    if (!(m.index >= ctx.from && !namedExampleBefore(ctx.text, m.index))) return null;
    return {
      ruleId: "spanishTypographyStyle",
      messageKey: "review_msg_spanish_decimal",
      range: { start: m.index, end: m.index + m[0].length },
      alternatives: [m[0].replace(/[.,]/gu, (c) => (c === "." ? "," : "."))],
    };
  },
  // es.yaml rule es.decimalComma frame 3
  "@es.decimalComma/3": (m: RegExpExecArray, ctx: DetectContext): MatchResult => {
    if (!(m.index >= ctx.from && !namedExampleBefore(ctx.text, m.index))) return null;
    const start = m.index + m[0].length - 1;
    return {
      ruleId: "spanishTypographyStyle",
      messageKey: "review_msg_typographic_symbol",
      range: { start, end: start + 1 },
      alternatives: [m[0].endsWith("2") ? "²" : "³"],
    };
  },
  // es.yaml rule es.quotes frame 1
  "@es.quotes/1": (m: RegExpExecArray, ctx: DetectContext): MatchResult => {
    return esQuotePair(m, ctx, "«", "»");
  },
  // es.yaml rule es.quotes frame 2
  "@es.quotes/2": (m: RegExpExecArray, ctx: DetectContext): MatchResult => {
    return esQuotePair(m, ctx, "‘", "’");
  },
};

/** The findings filters, by rule ("@<rule id>/filter"). */
export const FILTERS: Readonly<Record<string, FindingsFilter>> = {
  // es.yaml rule es.dashes filter
  "@es.dashes/filter": (ctx: DetectContext, findings: RawFinding[]): RawFinding[] => {
    const seen = new Set<number>();
    return findings.filter((f) => !seen.has(f.range.start) && !!seen.add(f.range.start));
  },
};

/** The Review detectors of rules with code, by rule ("@<rule id>"). */
export const DETECTORS: Readonly<Record<string, Detector>> = {};

/** The typing rules with code, by rule ("@<rule id>"). */
export const LIVE: Readonly<Record<string, LiveCode>> = {};
